S_6 = [
('internet-infrastructure', 'Internet Infrastructure', [
('Pick one small service first: a local wifi network, a shared mast, or a small data room. Define it for one area.', 'Map one town block: 120 homes, 15 shops; choose a wifi service for those 135 sites only.'),
('Compare three models: build and own, lease from a carrier, or share with a partner. Judge each by cost per connected site.', 'Own build {c} 300 per site, lease {c} 120 plus monthly fee, share {c} 150: compare over 5 years.'),
('Check the spectrum, cable-route, tower and telecom licence rules with the regulator before any build.', 'Licence table row: operator licence, route permit, tower permit, safety rule; each has an owner and a date checked.'),
('Protect network data: log only what you must, lock the equipment room, and plan for outages and backups.', 'Outage sheet: a power backup of 4 hours, a spare router, and a call list for faults.'),
('Prove the service with a pilot: measure speed, uptime and fault fix time for 20 sites.', 'Pilot result: 20 sites, 99% uptime over 30 days, median fix time 5 hours; publish the numbers.'),
('Price per site: build cost spread over years, plus running cost, plus margin. Calculate the payback.', 'Build 60 sites at {c} 300 = 18000. Fee {c} 15 per month x 60 = 900 per month. Payback 18000 / 900 = 20 months.'),
('Plan the people and partners: a licensed installer, a power supplier, a site owner, and a support person.', 'Roster: installer on call, two site owners signed, one support person on shift 8 am to 8 pm.'),
('Launch with a go or no-go rule: 40 paying sites in 3 months and uptime above 98%.', 'Month 3 count: 46 sites, 99% uptime: go; 22 sites: fix the offer, do not build more.')]),
('online-therapy', 'Online Therapy', [
('Plan a service for one need and one group, for example sleep stress in office workers. Design it as a planning study only.', 'Plan page: group of adults aged 25 to 40, one need, session length 50 minutes, no clinical work done by you.'),
('Compare three models: a platform that lists licensed therapists, a clinic that you partner with, and group sessions led by a licensed professional.', 'Listing {c} 5 per booking, partner clinic shares {c} 20 per session, group {c} 8 per seat: compare by margin and safety.'),
('Check licensing, privacy, consent and emergency rules with the health regulator. Partner with a licensed firm; do not give therapy yourself.', 'Rules table: licence of each therapist, consent form, emergency plan, cross-border rule; each has a date checked.'),
('Treat health data as the most sensitive data: collect the least, encrypt it, and set who may read it.', 'Access sheet: only the therapist and the client see notes; the admin sees bookings only.'),
('Gather proof the careful way: partner feedback forms, anonymous and with consent. Never publish client stories.', 'Survey: 30 clients, 24 say booking was easy and 21 would return; report the counts only.'),
('Price per session after the partner share: fee less therapist pay, platform cost and tax. Calculate the margin.', 'Session fee {c} 60. Therapist {c} 36, platform {c} 6, payment {c} 2: left {c} 16. 40 sessions give 640.'),
('List the roles: licensed therapists (partners), a client support person, and a safety contact. Write a handover rule.', 'Shift sheet: support person answers within 2 hours; urgent cases go to the emergency line the same hour.'),
('Decide a go or no-go rule: 3 licensed partners signed, the emergency plan tested, and 25 booked sessions in 6 weeks.', 'Week 6 check: 3 partners, plan tested, 31 bookings: go; plan not tested: no-go.')]),
('drones', 'Drones', [
('Choose one job to study: farm survey, roof check, or event photo. Plan it first; do no flying yet.', 'Job page: survey of 20 farm plots, 4 flights, one report per plot; planning only.'),
('Compare three models: partner with a licensed operator, buy and run drones with licensed pilots, or sell data from a partner.', 'Partner {c} 40 per plot, own drone {c} 25 plus pilot, data resale {c} 15: compare by margin and risk.'),
('Check aviation rules: pilot licence, drone registration, no-fly zones, insurance and privacy. Partner with a licensed firm for all flying.', 'Rules table: pilot licence, registration, flight permit, insurance cover, privacy notice; each has a date checked.'),
('Handle images and location data with care: store them safely, blur faces, and delete on a set date.', 'Rule: raw images deleted after 90 days; client gets the report and a copy of the cleaned images.'),
('Show proof with a sample report built from partner data: before and after, with date and area.', 'Sample: 20 plots surveyed, 3 with water stress found, report ready in 2 days.'),
('Price per job: partner cost, processing, report and margin. Calculate the margin.', 'Partner flight {c} 40 per plot, processing {c} 10, price {c} 80: margin {c} 30 per plot; 20 plots give 600.'),
('List roles: licensed pilot (partner), data analyst, and client lead. Write a one-page job brief.', 'Brief: area, date, weather limit, deliverable, price, safety contact.'),
('Launch with a go or no-go rule: 3 paid pilot jobs in 8 weeks, all done by a licensed partner, with a margin above 25%.', 'Week 8 count: 4 jobs at 33% margin: go; permit not in place: no-go.')]),
('cloud-migration-as-a-service', 'Cloud Migration As A Service', [
('Start with one type of client and one system, for example a small firm with a file server. Define a fixed scope.', 'Offer: move 1 file server of 500 GB and 25 users in 2 weeks, with a rollback plan.'),
('Compare three models: lift and shift, re-build for the cloud, and managed move by a partner. Judge by cost and risk.', 'Lift and shift {c} 2000, rebuild {c} 9000, managed {c} 4000: choose by the client need and downtime.'),
('Check data law, contract terms, data location rules and the client sector rules before any move.', 'Rules table: data location, contract clause, backup rule, exit rule; each has an owner and a date checked.'),
('Protect client data: use least access, keep keys with the client, log every change, and test the backup.', 'Checklist: access list signed, keys held by the client, restore test passed on day 10.'),
('Prove the method with a pilot: record downtime, cost change and faults found for one client.', 'Pilot: downtime 3 hours, monthly cost fell from 500 to 380, 2 faults fixed.'),
('Price the project fee plus a monthly support fee. Calculate the margin.', 'Project fee {c} 4000, cost 20 days x {c} 100 = 2000, margin 2000. Support {c} 200 per month x 12 = 2400.'),
('Plan the team: a cloud engineer, a data checker, and a client contact. Add a partner for security review.', 'Roster: engineer 20 days, checker 3 days, partner review 2 days, client contact weekly call.'),
('Launch with a go or no-go rule: 2 paid pilots in 8 weeks, each with a tested rollback and zero data loss.', 'Week 8 count: 2 pilots, rollback tested, no data loss: go; one data loss: stop and fix first.')]),
('nanotechnology-in-medicine', 'Nanotechnology In Medicine', [
('Pick one narrow area to study, for example a coating, a test strip, or a delivery material. Plan it as a study only.', 'Study page: one question, one material, one use; no clinical claim and no patient work by you.'),
('Compare three models: partner with a licensed lab, license an existing method, or serve as a research service. Judge by time and cost.', 'Lab partner {c} 500 per run, license {c} 200 per month, service {c} 300 per report: compare by speed and risk.'),
('Check medical device, drug, ethics and lab safety rules. Partner with a licensed firm for all testing and trials.', 'Rules table: lab licence, ethics approval, device class, safety rule; each has a date checked.'),
('Keep trial data clean: record who, what and when, keep an audit trail, and protect any patient data.', 'Data log: each sample has an ID, date, handler and storage place; no patient names.'),
('Gather proof from partner results: a peer-reviewed method, a lab report, and a test date. Never claim a cure.', 'Proof sheet: 3 lab runs, same result 3 times, report dated and signed by the lab.'),
('Plan the cost of research: lab runs, materials, review and a reserve. Calculate the total.', '6 runs x {c} 500 = 3000. Materials {c} 400, review {c} 300, reserve 10% of 3700 = 370: total 4070.'),
('List partners: a licensed lab, a clinical adviser, a regulatory adviser, and a university group. Write who signs off what.', 'Sign-off table: lab signs results, adviser signs the safety review, you sign the plan.'),
('Decide a go or no-go rule: a signed lab partner, a safety review passed, and a funded study plan before any spend.', 'Check: partner signed, review passed, 4070 funded: go; review open: no-go.')]),
('e-commerce-inventory-management', 'E-Commerce Inventory Management', [
('Start with one shop type and one stock list. Count what you hold today and set one reorder rule.', 'Stock count of 60 items across 2 shelves; reorder when an item falls to 5 units.'),
('Compare three models: own stock, supplier ships direct, and a partner warehouse. Judge by cash tied up and delivery days.', 'Own stock {c} 5000 tied up, direct ship {c} 0 with 7 days, warehouse {c} 1 per item with 2 days: compare.'),
('Check the rules for stock records, tax on stock, product safety and returns before you scale.', 'Rules table: stock record rule, tax on stock, labels, returns; each has a date checked.'),
('Keep one clean stock sheet: item code, count, location, last count date. Count weekly and fix gaps.', 'Sheet of 60 items; the weekly count finds 2 gaps; fix both and note why.'),
('Prove the method with before and after: stock-outs and dead stock over 8 weeks.', 'Stock-outs fell from 9 to 2 per month; dead stock fell from 18% to 9%.'),
('Calculate the reorder point: daily sales times lead time, plus a safety buffer.', 'Sales 6 per day, lead time 5 days: 30, plus buffer 10 = reorder at 40 units.'),
('Assign roles: a stock counter, a buyer, and a supplier contact. Write a weekly checklist.', 'Weekly list: count Monday, order Tuesday, receive Thursday, update sheet the same day.'),
('Launch with a go or no-go rule: stock accuracy above 95% and stock-outs under 3 per month for 2 months.', 'Month 2 check: accuracy 97%, stock-outs 2: go; accuracy 90%: fix counts first.')]),
('online-car-dealership', 'Online Car Dealership', [
('Sell one car type to one buyer group first, for example used city cars under a set price. Narrow the stock.', 'Start with 10 used city cars, 5 to 8 years old, for first-time buyers.'),
('Compare three models: own stock, listing for private sellers, and a partner dealer network. Judge by cash and margin.', 'Own stock {c} 8000 per car, listing fee {c} 150, partner share {c} 400: compare by cash tied up.'),
('Check the dealer licence, vehicle title transfer, tax, warranty and consumer rules before the first sale.', 'Rules table: dealer licence, title transfer, sales tax, warranty text, returns rule; each has a date checked.'),
('Verify each car: history report, mileage check, ID of the seller and a signed condition sheet.', 'File per car: history report, 12-point check, 20 photos, owner ID seen and recorded.'),
('Build trust with full photos, a clear condition report and a short return window.', 'Listing shows 20 photos, a 12-point report and a 7-day return rule; 60 views lead to 3 test drives.'),
('Calculate the margin per car: buy price, repair, listing and delivery costs, and sale price.', 'Buy 8000, repair 400, delivery 150, listing 100: cost 8650. Sell 9500: margin 850.'),
('List the roles: an inspector, a title agent, a delivery driver, and a support person. Partner with a licensed lender.', 'Roster: inspector 2 days per week, title agent per sale, lender partner for finance only.'),
('Launch with a go or no-go rule: 6 cars sold in 8 weeks at a margin above 8%.', 'Week 8 count: 7 cars, margin 9%: go; 3 cars: change the stock and price.')]),
('car-charging-stations', 'Car Charging Stations', [
('Start with one site type, for example a shop car park with 4 bays. Count cars and dwell time first.', 'Site study: 200 cars per day, average stay 90 minutes, 4 bays chosen.'),
('Compare three models: own and run, host with a revenue share, and a partner network. Judge by cost and income.', 'Own {c} 6000 per bay, host share 20% of sales, partner network {c} 0 with 30% share: compare payback.'),
('Check power connection, electrical safety, planning permit and payment rules. Use a licensed electrician for all work.', 'Rules table: grid connection, electrical permit, site lease, safety signs, payment rule; each has a date checked.'),
('Handle user data and payments with care: store little, use a secure payment partner, and log faults.', 'Rule: the payment partner holds card data; you keep session count and kWh only.'),
('Prove demand with a count: cars per hour near the site and a survey of drivers.', 'Count: 12 electric cars per day pass; 40 drivers surveyed, 28 would charge there.'),
('Calculate payback: install cost, power cost per kWh and price per kWh.', '4 bays x {c} 6000 = 24000. Sell at {c} 0.40, pay {c} 0.25: margin 0.15 per kWh. 400 kWh per day x 0.15 = 60 per day; 24000 / 60 = 400 days.'),
('List the partners: a licensed electrician, a hardware supplier, a site owner, and a maintenance contact.', 'Roster: electrician for install and yearly check, supplier warranty 2 years, repair call within 48 hours.'),
('Launch with a go or no-go rule: a signed site lease, an approved grid connection and 15 sessions a day expected.', 'Check: lease signed, connection approved, forecast 18 sessions: go; no connection date: no-go.')]),
('smart-apparel', 'Smart Apparel', [
('Pick one garment and one feature, for example a work vest that tracks heat. Define one user group first.', 'Product page: a vest for outdoor workers that warns at body heat over a set level; 1 size range.'),
('Compare three models: own brand with a contract maker, add sensors to another brand, or sell the data service only.', 'Own brand {c} 30 per unit, add-on {c} 12, data service {c} 3 per month: compare by margin and effort.'),
('Check safety, battery, wash, radio and product claim rules before you sell. Test with an approved lab.', 'Rules table: battery safety, radio rule, skin contact rule, care label, claim wording; each has a date checked.'),
('Protect body and location data: collect the least, ask for consent, and let users delete data.', 'App asks 3 consents; the user can delete data in 2 taps.'),
('Prove the product with a wear trial: 20 users, 2 weeks, with wash and fit feedback.', 'Trial: 20 users, 17 rate comfort good, 2 sensors failed after 10 washes; fix and retest.'),
('Calculate unit cost and price: fabric, sensor, battery, sewing, packing and returns share.', 'Fabric 12, sensor 14, battery 5, sewing 6, packing 3, returns 2: cost 42. Price 79 leaves 37.'),
('List partners: a garment maker, a sensor supplier, a test lab, and an app builder. Write a one-page spec.', 'Spec: size range, wash cycles 30, battery 7 days, delivery date, test report needed.'),
('Launch with a go or no-go rule: 50 pre-orders in 6 weeks and a passed lab test.', 'Week 6 count: 58 pre-orders, lab passed: go; test failed: no-go.')]),
('alternative-protein-food-products', 'Alternative Protein Food Products', [
('Start with one product and one meal moment, for example a plant-based snack for lunch. Test taste with a small group.', 'Taste test: 30 people try 3 recipes; keep the one that 20 or more rate good.'),
('Compare three models: make your own, use a contract food maker, or sell a recipe to a producer. Judge by cost and control.', 'Own kitchen {c} 2.00 per pack, contract maker {c} 1.40 with a minimum order, recipe sale {c} 0.20 per pack: compare.'),
('Check food safety, labelling, allergen and claim rules. Use a licensed kitchen and a food adviser; state planning only.', 'Rules table: food licence, label text, allergen list, protein claim rule, shelf-life test; each has a date checked.'),
('Keep batch records: ingredient source, date, batch number and storage temperature, so a recall can trace it.', 'Batch sheet: 5 fields per batch; a mock recall finds all packs within 1 hour.'),
('Prove demand and quality with a tasting event and a pre-order list; record the counts honestly.', 'Event: 80 tasters, 52 rate good, 25 pre-orders at the stall.'),
('Calculate cost per pack: ingredients, packing, making, cold chain and margin.', 'Ingredients 0.90, packing 0.30, making 0.40, cold chain 0.20: cost 1.80. Price 3.00 leaves 1.20; 1000 packs give 1200.'),
('List partners: a licensed food maker, an ingredient supplier, a lab for shelf-life tests and a shop buyer.', 'Roster: maker books 2 runs, supplier gives a spec sheet, lab tests day 0, 14 and 28.'),
('Launch with a go or no-go rule: a passed safety review, a shelf life of 21 days, and 200 packs sold in 4 weeks.', 'Week 4 count: 240 packs, review passed: go; shelf life of 10 days: no-go.')]),
]
